from lib import *
S = SS('x36')
steps = [
    step("NESTED 在 MySQL 那个连接上留下的语句。outer 先插 outer-1,调 NESTED 的 inner,再插 outer-2。inner 成功:SET autocommit=0、insert outer-1、SAVEPOINT `SAVEPOINT_1`、insert inner、RELEASE SAVEPOINT、insert outer-2、COMMIT、SET autocommit=1;提交后表里 outer-1+inner+outer-2。inner 失败被 outer 捕获:同样的开头,但 insert inner 之后是 ROLLBACK TO SAVEPOINT `SAVEPOINT_1`、RELEASE SAVEPOINT,接着 insert outer-2、COMMIT;表里 outer-1+outer-2。整个过程只有一个事务一个连接,NESTED 就是 SAVEPOINT。", t=tl(S(1)), mark=lidx(S(1), 'ROLLBACK TO SAVEPOINT', 'inner 失败'), done=lidx(S(1), 'inner 成功', 'SAVEPOINT `SAVEPOINT_1`', 'RELEASE SAVEPOINT'), b=bars([['inner 成功:表里行数', 3, '3(outer-1、inner、outer-2)'], ['inner 失败被捕获:表里行数', 2, '2(outer-1、outer-2)'], ['事务个数', 1, '1(一个连接一个 COMMIT)']], 3, done=[0], mark=[1], cur=[2]), kv=KV([['NESTED 的开始', 'SAVEPOINT `SAVEPOINT_1`'], ['inner 成功', 'RELEASE SAVEPOINT'], ['inner 失败', 'ROLLBACK TO SAVEPOINT,再 RELEASE'], ['整个事务', '仍然只有一个 COMMIT']], ['NESTED 的开始'])),
    step("NESTED 每次要多花多少(一个事务里调用内层方法 2000 次,各跑 3 次)。REQUIRED:132、269、128 ms,每次约 64 到 135 µs。NESTED:358、791、300 ms,每次约 150 到 396 µs。NESTED 每次多出 SAVEPOINT 和 RELEASE 两条语句,耗时是 REQUIRED 的两倍多;中间那次两组都慢(269 与 791 ms),运行间的抖动不小。", t=tl(S(2)), mark=lidx(S(2), 'NESTED 358 ms'), done=lidx(S(2), 'REQUIRED 132 ms'), b=bars([['REQUIRED 2000 次(第 1 次)ms', 132, '132'], ['NESTED 2000 次(第 1 次)ms', 358, '358'], ['REQUIRED 2000 次(第 3 次)ms', 128, '128'], ['NESTED 2000 次(第 3 次)ms', 300, '300']], 358, done=[0, 2], mark=[1, 3]), kv=KV([['REQUIRED', '约 64 µs 每次(干净的两次)'], ['NESTED', '约 150 到 180 µs 每次'], ['额外的语句', 'SAVEPOINT + RELEASE SAVEPOINT'], ['噪声', '中间那次两组都慢到 135 与 396 µs']], ['额外的语句'])),
    step("JpaTransactionManager 能不能用 NESTED。默认设置:NestedTransactionNotSupportedException:Transaction manager does not allow nested transactions by default - specify 'nestedTransactionAllowed' property with value 'true'。把 setNestedTransactionAllowed(true) 打开,用 Hibernate:仍然是 NestedTransactionNotSupportedException:JpaDialect does not support savepoints - check your JPA provider's capabilities。JDBC 的 DataSourceTransactionManager 支持 NESTED,但 Hibernate 的 JPA 事务管理器不支持。", t=tl(S(3)), mark=lidx(S(3), 'setNestedTransactionAllowed(true)'), done=lidx(S(3), 'setNestedTransactionAllowed(false)'), b=bars([['JpaTransactionManager 默认:NESTED 可用', 0, '否'], ['setNestedTransactionAllowed(true) 后:NESTED 可用', 0, '否(JpaDialect 不支持 savepoint)'], ['DataSourceTransactionManager:NESTED 可用', 1, '是']], 1, mark=[0, 1], done=[2]), kv=KV([['JpaTransactionManager 默认', '要先打开 nestedTransactionAllowed'], ['打开之后', 'JpaDialect does not support savepoints'], ['Hibernate', '这个 JpaDialect 不支持 savepoint'], ['能用的', 'DataSourceTransactionManager(JDBC)']], ['Hibernate'])),
]
A = mkartx('x36', 36, 'Spring,事务,NESTED,Savepoint,嵌套事务,真实验证,动画演示',
    '实测 NESTED 就是 JDBC Savepoint:MySQL 上依次出现 SAVEPOINT、(失败时 ROLLBACK TO SAVEPOINT)、RELEASE SAVEPOINT,整个过程只有一个 COMMIT;每次多出两条语句,耗时是 REQUIRED 的两倍多;JpaTransactionManager 默认不允许 NESTED,打开之后 Hibernate 的 JpaDialect 仍然不支持 savepoint。',
    'NESTED 嵌套事务在数据库里到底是什么?它比普通加入外层事务贵多少?为什么用 JPA 的时候 NESTED 会直接报错?这篇在 Spring Framework 7.0.9、Hibernate 和 MySQL 26.7.0 上把语句和报错逐条量出来。',
    [('1 个 COMMIT', 'NESTED 的 inner 成功或失败时,整个过程在 MySQL 上都只有一个事务、一个 COMMIT'), ('约 2 倍多', '一个事务里调用内层方法,NESTED 相比 REQUIRED 每次的耗时(多出 SAVEPOINT 和 RELEASE 两条语句)'), ('JpaDialect', '用 JPA / Hibernate 时即使打开 nestedTransactionAllowed,NESTED 仍报“JpaDialect does not support savepoints”')],
    [('就是 Savepoint', '<p>NESTED 在同一个连接上用 SAVEPOINT 和 ROLLBACK TO SAVEPOINT 实现。</p>'),
     ('代价', '<p>每次多两条语句,耗时是 REQUIRED 的两倍多。</p>'),
     ('JPA 不行', '<p>JpaTransactionManager 默认不允许,打开后 Hibernate 的 JpaDialect 也不支持 savepoint。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 + DataSourceTransactionManager + HikariCP + 自己起的 MySQL 26.7.0 + Hibernate(Boot 4.0.8 的 BOM);第二节的耗时每次运行抖动大(中间那次 REQUIRED 269 ms、NESTED 791 ms),只能当量级参考;general_log 开在这个实例上',
     '没有验证:Savepoint 在 InnoDB 里对行锁的释放行为;PostgreSQL 等其它数据库;JTA 下的 NESTED;JPA 提供商换成 EclipseLink 时的支持;大量嵌套深度(1000 层)下 savepoint 的资源开销'],
    '嵌套事务与 Savepoint')
